select 'literary_places' as dataset,count(*) as records from public.literary_places
union all select 'literary_characters',count(*) from public.literary_characters
union all select 'literary_scenes',count(*) from public.literary_scenes;


-- Character perspectives and free exploration
create or replace function public.save_literary_route(p_attempt uuid,p_content jsonb,p_duration integer,p_model text,p_prompt text) returns uuid
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); gid uuid; stop jsonb; ids text[]:='{}'; minutes integer:=0; perspective text:=coalesce(p_content->>'perspective','gringoire');
begin
 if uid is null then raise exception 'Authentication required'; end if;
 if perspective not in('gringoire','esmeralda','quasimodo','claude','free') then raise exception 'Invalid perspective'; end if;
 if p_duration is null or p_duration not in(60,90,120) or p_model is null or length(p_model) not between 1 and 100 or p_prompt is null or length(p_prompt) not between 1 and 60000 then raise exception 'Invalid metadata'; end if;
 if jsonb_typeof(p_content->'title') is distinct from 'string' or length(p_content->>'title') not between 1 and 80 or jsonb_typeof(p_content->'summary') is distinct from 'string' or length(p_content->>'summary') not between 1 and 500 or jsonb_typeof(p_content->'stops') is distinct from 'array' then raise exception 'Invalid content'; end if;
 if jsonb_array_length(p_content->'stops') not between 3 and 4 then raise exception 'Invalid stops'; end if;
 for stop in select * from jsonb_array_elements(p_content->'stops') loop
  if not exists(select 1 from public.literary_places where id=stop->>'place_id' and map_reference is not null and jsonb_typeof(map_reference)='object')
   or (stop->>'place_id')=any(ids) or jsonb_typeof(stop->'reason') is distinct from 'string' or length(stop->>'reason') not between 1 and 300
   or jsonb_typeof(stop->'scene_id') is distinct from 'string' or not exists(select 1 from public.literary_scenes where id=stop->>'scene_id')
   or coalesce(stop->>'minutes','') !~ '^[0-9]{1,2}$' then raise exception 'Invalid stop'; end if;
  -- The selected scene must belong to this place or its nested spaces, and support the selected perspective (free mode accepts any sourced scene).
  if not exists(
   with recursive family as (
    select id from public.literary_places where id=stop->>'place_id'
    union all select p.id from public.literary_places p join family f on p.data->>'parent_id'=f.id
   ) select 1 from public.literary_scenes s join family f on f.id=s.place_id,
   lateral jsonb_array_elements(s.data->'character_relations') r
   where s.id=stop->>'scene_id' and (perspective='free' or (r->>'character_id'=perspective and r->>'relation' in('present','passed_through','spectator_inside','at_window','resident','visited_in_backstory','lived_as_infant','repeated_visit_reported','passed_through_reported','uses_room','present_under_alias','nearby_spectator','passed_street_entrance','outside_only','testifies_inside','visited_reported','boat_passage','present_as_infant','approached_or_at_bridgehead_not_confirmed_crossing')))
  ) then raise exception 'Unsupported character-scene relation'; end if;
  if (stop->>'minutes')::integer not between 5 and 30 then raise exception 'Invalid duration'; end if;
  minutes:=minutes+(stop->>'minutes')::integer;
  ids:=array_append(ids,stop->>'place_id');
 end loop;
 if minutes>p_duration-10 then raise exception 'Exceeds duration'; end if;
 update public.literary_attempts set used=true where id=p_attempt and user_id=uid and not used and created_at>now()-interval '5 minutes';
 if not found then raise exception 'Invalid reservation'; end if;
 insert into public.literary_routes(user_id,attempt_id,content,duration,model) values(uid,p_attempt,p_content,p_duration,p_model) returning id into gid;
 insert into public.literary_route_prompts(route_id,user_id,prompt) values(gid,uid,p_prompt);
 return gid;
end $$;



-- Administrator-managed test account quota exceptions
-- Administrator-managed quota exceptions. Clients cannot read or modify the list.
create table if not exists public.literary_test_accounts (
 user_id uuid primary key references auth.users(id) on delete cascade,
 created_at timestamptz not null default now()
);
alter table public.literary_test_accounts enable row level security;
revoke all on public.literary_test_accounts from public,anon,authenticated;

create or replace function public.is_literary_test_account() returns boolean
language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from public.literary_test_accounts where user_id=auth.uid());
$$;
revoke all on function public.is_literary_test_account() from public,anon;
grant execute on function public.is_literary_test_account() to authenticated;

create or replace function public.reserve_literary_generation() returns uuid
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); attempt uuid;
begin
 if uid is null then raise exception 'Authentication required'; end if;
 if not exists(select 1 from public.profiles where id=uid and length(trim(first_name))>0 and length(trim(last_name))>0) then raise exception 'Complete your profile'; end if;
 perform pg_advisory_xact_lock(hashtextextended('literary:'||uid::text,0));
 if not public.is_literary_test_account() and (select count(*) from public.literary_attempts where user_id=uid and created_at>now()-interval '24 hours')>=5 then raise exception 'Daily generation limit reached'; end if;
 insert into public.literary_attempts(user_id) values(uid) returning id into attempt;
 return attempt;
end $$;
revoke all on function public.reserve_literary_generation() from public,anon;
grant execute on function public.reserve_literary_generation() to authenticated;

commit;
-- Personal pins are private by default. Public readers never receive author identifiers.
create table if not exists public.literary_echoes (
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references auth.users(id) on delete cascade,
 lat double precision not null check (lat between 48.80 and 48.92),
 lng double precision not null check (lng between 2.25 and 2.43),
 body text not null check (char_length(btrim(body)) between 1 and 1000),
 is_public boolean not null default false,
 created_at timestamptz not null default now()
);
alter table public.literary_echoes enable row level security;
revoke all on public.literary_echoes from anon, authenticated;
grant select, delete on public.literary_echoes to authenticated;
create policy "Read own echoes" on public.literary_echoes for select to authenticated using (user_id = auth.uid());
create policy "Remove own echoes" on public.literary_echoes for delete to authenticated using (user_id = auth.uid());
create index if not exists literary_echoes_public on public.literary_echoes(created_at desc) where is_public;
create or replace function public.read_city_echoes() returns table(id uuid, lat double precision, lng double precision, body text, created_at timestamptz)
language sql stable security definer set search_path = '' as $$
 select e.id,e.lat,e.lng,e.body,e.created_at from public.literary_echoes e where e.is_public order by e.created_at desc limit 200;
$$;
revoke all on function public.read_city_echoes() from public;
grant execute on function public.read_city_echoes() to anon,authenticated;
create or replace function public.save_city_echo(p_lat double precision,p_lng double precision,p_body text,p_public boolean) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
 if auth.uid() is null then raise exception 'Sign in required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text || ':echoes',0));
 if (select count(*) from public.literary_echoes where user_id=auth.uid() and created_at>now()-interval '24 hours') >= 20 then raise exception 'Daily echo limit'; end if;
 insert into public.literary_echoes(user_id,lat,lng,body,is_public) values(auth.uid(),p_lat,p_lng,btrim(p_body),p_public) returning id into v_id;
 return v_id;
end; $$;
revoke all on function public.save_city_echo(double precision,double precision,text,boolean) from public;
grant execute on function public.save_city_echo(double precision,double precision,text,boolean) to authenticated;
create table if not exists public.literary_journey_choices (
 user_id uuid primary key references auth.users(id) on delete cascade,
 route_id uuid not null references public.literary_routes(id) on delete cascade,
 updated_at timestamptz not null default now()
);
alter table public.literary_journey_choices enable row level security;
revoke all on public.literary_journey_choices from anon,authenticated;
grant select,insert,update on public.literary_journey_choices to authenticated;
create policy "Read own journey choice" on public.literary_journey_choices for select to authenticated using(user_id=auth.uid());
create policy "Choose own saved journey" on public.literary_journey_choices for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.literary_routes r where r.id=route_id and r.user_id=auth.uid()));
create policy "Change own journey choice" on public.literary_journey_choices for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and exists(select 1 from public.literary_routes r where r.id=route_id and r.user_id=auth.uid()));
begin;
-- A generation attempt can yield up to three comparable options; quota still counts once.
alter table public.literary_routes drop constraint if exists literary_routes_attempt_id_key;
create or replace function public.save_literary_options(p_attempt uuid,p_options jsonb,p_duration integer,p_model text,p_prompt text) returns uuid[]
language plpgsql security definer set search_path='' as $$
declare option jsonb; result uuid[]:='{}'; route_id uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if jsonb_typeof(p_options) is distinct from 'array' or jsonb_array_length(p_options) not between 1 and 3 then raise exception 'Invalid options'; end if;
 perform 1 from public.literary_attempts where id=p_attempt and user_id=auth.uid() and not used and created_at>now()-interval '5 minutes' for update;
 if not found then raise exception 'Invalid reservation'; end if;
 for option in select * from jsonb_array_elements(p_options) loop
  update public.literary_attempts set used=false where id=p_attempt and user_id=auth.uid();
  route_id:=public.save_literary_route(p_attempt,option,p_duration,p_model,p_prompt);
  result:=array_append(result,route_id);
 end loop;
 return result;
end $$;
revoke all on function public.save_literary_options(uuid,jsonb,integer,text,text) from public;
grant execute on function public.save_literary_options(uuid,jsonb,integer,text,text) to authenticated;
commit;
